const item=$input.first();
const incoming=item.json||{};
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const parse=value=>{if(object(value))return value;if(typeof value==='string'){try{const parsed=JSON.parse(value);return object(parsed)?parsed:{}}catch{return {}}}return {}};
const packet=parse(incoming.specialist_packet);
const packetValid=packet.contract==='specialist_packet'&&packet.contract_version==='1.0'&&typeof packet.task_id==='string'&&packet.task_id.trim()&&packet.specialist_id==='engineering_calculation_specialist'&&Number.isInteger(packet.attempt)&&packet.attempt>=1&&typeof packet.objective==='string'&&packet.objective.trim()&&object(packet.inputs)&&object(packet.controls)&&Array.isArray(packet.acceptance_criteria)&&Array.isArray(packet.artifact_refs);
const entries=Object.entries(item.binary||{});
const trajectories=entries.filter(([,file])=>/\.dev$/i.test(String(file?.fileName||'')));
const surfaces=entries.filter(([,file])=>/\.(?:cps3|grd|grid|txt)$/i.test(String(file?.fileName||'')));
let gate='ready';
if(!packetValid)gate='invalid_packet';else if(!trajectories.length||surfaces.length!==1)gate='missing_or_ambiguous_files';
const binary={};
const bodyParameters=[];
for(let i=0;i<trajectories.length;i++){const field=`trajectory_${i}`;binary[field]=trajectories[i][1];bodyParameters.push({parameterType:'formBinaryData',name:'trajectory_files',inputDataFieldName:field});}
if(surfaces.length===1){binary.surface_file=surfaces[0][1];bodyParameters.push({parameterType:'formBinaryData',name:'surface_file',inputDataFieldName:'surface_file'});}
return [{json:{specialist_packet:packet,request_ready:gate==='ready',adapter_gate:gate,trajectory_filenames:trajectories.map(([,file])=>String(file.fileName||'')),surface_filename:surfaces.length===1?String(surfaces[0][1].fileName||''):null,body_parameters:bodyParameters},binary}];

const prepared=$('Prepare trajectory intersection request').first().json||{};
const packet=prepared.specialist_packet||{};
let response=$json;if(response?.body&&typeof response.body==='object')response=response.body;
const finite=value=>typeof value==='number'&&Number.isFinite(value);
const results=Array.isArray(response?.results)?response.results:[];
const expected=Array.isArray(prepared.trajectory_filenames)?prepared.trajectory_filenames:[];
const valid=results.length===expected.length&&results.length>0&&results.every(value=>value&&typeof value.filename==='string'&&value.filename&&finite(value.intersection_md)&&finite(value.x)&&finite(value.y)&&finite(value.z));
const returnedNames=results.map(value=>value?.filename);
const filenamesMatch=valid&&expected.every(name=>returnedNames.includes(name))&&new Set(returnedNames).size===returnedNames.length;
const passed=valid&&filenamesMatch;
const status=passed?'succeeded':'retryable_error';
const summary=passed?`Math Service calculated ${results.length} DEV trajectory/CPS3 surface intersections in one batch.`:'Math Service returned an invalid or incomplete batch trajectory-intersection response.';
const calculation=passed?{results:results.map(value=>({filename:value.filename,intersection_md:value.intersection_md,x:value.x,y:value.y,z:value.z})),trajectory_count:results.length,result_mode:'computed_batch'}:{};
const reasonCodes=passed?['TRAJECTORY_INTERSECTION_BATCH_COMPUTED']:['MATH_SERVICE_BATCH_RESPONSE_INVALID'];
const checks=[{check:'math_service_batch_response_contract',passed:valid},{check:'one_result_per_trajectory_filename',passed:filenamesMatch},{check:'finite_intersection_coordinates',passed}];
const assumptions=['All trajectories and the surface use the same CRS, length units, vertical datum and Z sign convention.'];
const considered=[...expected.map(filename=>({kind:'dev_trajectory',filename})),{kind:'ascii_cps3_surface',filename:prepared.surface_filename}];
const decision={contract:'decision_record',contract_version:'1.0',objective:String(packet.objective||'Calculate trajectory/surface intersections.'),considered_inputs:considered,proposed_actions:[{action:'return_computed_batch'}],selected_action:{action:status,reason_codes:reasonCodes},rejected_actions:[],assumptions,evidence_refs:[],citations:[],tool_call_ids:['math-service:trajectory-intersection:batch'],unresolved_questions:passed?[]:[{id:'math_service_response',question:'Check the Math Service URL, every DEV/CPS3 input and the batch response.',type:'text'}],acceptance_check_results:checks};
return [{json:{specialist_result:{contract:'specialist_result',contract_version:'1.0',task_id:String(packet.task_id||'unknown'),specialist_id:'engineering_calculation_specialist',attempt:Number.isInteger(packet.attempt)?packet.attempt:1,status,summary,deliverables:passed?[{kind:'trajectory_surface_intersections',description:summary,artifact_refs:[]}]:[],artifact_refs:[],compact_data:{calculation,decision_record:decision,agent_tool_trace:[{name:'trajectory-intersection',tool_call_id:'math-service:trajectory-intersection:batch',status:passed?'completed':'error',stage:'calculation',sequence:1}]},assumptions,warnings:[],evidence:passed?[{source_ref:'math-service://trajectory-intersection',trajectory_filenames:expected,surface_filename:prepared.surface_filename,result_mode:'computed_batch'}]:[],self_check:{performed:true,passed,checks,reproducibility:'Repeat with the same DEV batch and ASCII CPS3 input.'},human_request:null,error:passed?null:{code:'MATH_SERVICE_BATCH_RESPONSE_INVALID',response},continuation:null}}}];

const x=$('Prepare trajectory intersection request').first().json||{};
const packet=x.specialist_packet||{};
const fatal=x.adapter_gate==='invalid_packet';
const questions=fatal?[]:[{id:'trajectory_files',question:'Upload one or more well trajectories as .dev files.',type:'file'},{id:'surface_file',question:'Upload exactly one ASCII CPS3 surface as .cps3, .grd, .grid or .txt.',type:'file'}];
const status=fatal?'fatal_error':'needs_input';
const code=fatal?'INVALID_CALCULATION_SPECIALIST_PACKET':'CALCULATION_FILES_REQUIRED';
const decision={contract:'decision_record',contract_version:'1.0',objective:String(packet.objective||'Validate batch trajectory-intersection input.'),considered_inputs:[{kind:'calculation_adapter_input',adapter_gate:x.adapter_gate,trajectory_count:(x.trajectory_filenames||[]).length,surface_filename:x.surface_filename}],proposed_actions:[{action:'call_math_service_batch'},{action:'request_files'}],selected_action:{action:status,reason_codes:[code]},rejected_actions:[{action:'call_math_service_batch',reason_codes:[code]}],assumptions:[],evidence_refs:[],citations:[],tool_call_ids:[],unresolved_questions:questions,acceptance_check_results:[{check:'one_or_more_trajectories_and_exactly_one_surface',passed:false}]};
return [{json:{specialist_result:{contract:'specialist_result',contract_version:'1.0',task_id:String(packet.task_id||'unknown'),specialist_id:'engineering_calculation_specialist',attempt:Number.isInteger(packet.attempt)?packet.attempt:1,status,summary:fatal?'Invalid specialist_packet supplied to Calculation Adapter.':'One or more valid DEV trajectories and exactly one CPS3 surface are required.',deliverables:[],artifact_refs:[],compact_data:{adapter_gate:x.adapter_gate,decision_record:decision},assumptions:[],warnings:[],evidence:[],self_check:{performed:false,passed:false,checks:[],reproducibility:''},human_request:fatal?null:{kind:'needs_input',questions},error:fatal?{code}:null,continuation:null}}}];
